var documenterSearchIndex = {"docs":
[{"category":"section","location":"guide/#User-Guide","page":"User Guide","text":"This guide is automatically generated from the comprehensive USER_GUIDE.md.\n\nFor the most up-to-date information, see USER_GUIDE.md in the repository.\n\n\n\nPages = [\"guide.md\"]\nDepth = 3\n\n","title":"User Guide"},{"category":"section","location":"guide/#Quick-Start","page":"User Guide","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n","title":"Quick Start"},{"category":"section","location":"guide/#Core-Functions","page":"User Guide","text":"","title":"Core Functions"},{"category":"section","location":"guide/#Pattern-Detection","page":"User Guide","text":"# Get missing data pattern matrix (boolean)\npattern = missing_pattern(df)\n\n# Get percentage of missing values per column\npercentages = missing_percentage(df)\n\n# Get count of missing values per column\ncounts = missing_count(df)","title":"Pattern Detection"},{"category":"section","location":"guide/#Visualizations","page":"User Guide","text":"# Missing data matrix heatmap\nfig1 = plot_missing_matrix(df)\n\n# Bar chart of missing percentages\nfig2 = plot_missing_bars(df)\n\n# Correlation matrix of missingness\nfig3 = plot_missing_correlation(df)\n\n# Combined overview dashboard\nfig4 = plot_missing_overview(df)","title":"Visualizations"},{"category":"section","location":"guide/#All-in-One-Analysis","page":"User Guide","text":"# Interactive mode (default)\nresults = diagnose_missing(df)\n\n# Batch mode (generate HTML report)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n","title":"All-in-One Analysis"},{"category":"section","location":"guide/#Workflows","page":"User Guide","text":"","title":"Workflows"},{"category":"section","location":"guide/#Interactive-Analysis","page":"User Guide","text":"using MissingDataViz, DataFrames\n\ndf = # your data loading\n\n# Automatic analysis with plot display\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall percentage: \", results[:stats][:overall_percentage], \"%\")\n\n# Access per-column statistics\nfor (col, stats) in results[:stats][:columns]\n    println(\"$col: $(stats[:percentage])% missing\")\nend","title":"Interactive Analysis"},{"category":"section","location":"guide/#Batch-Reporting","page":"User Guide","text":"# Generate standalone HTML report\nresults = diagnose_missing(df, report=true, output=\"analysis.html\")\n\nprintln(\"Report saved to: \", results[:report_path])\n# → Report saved to: /absolute/path/to/analysis.html\n\n","title":"Batch Reporting"},{"category":"section","location":"guide/#Exporting-Plots","page":"User Guide","text":"All plotting functions return Makie.Figure objects. Export them using CairoMakie.save().\n\nusing CairoMakie\n\n# Generate a plot\nfig = plot_missing_matrix(df)\n\n# PNG (default 300 DPI)\nsave(\"output.png\", fig)\n\n# PDF (vector format, high quality)\nsave(\"output.pdf\", fig)\n\n# SVG (vector format, editable)\nsave(\"output.svg\", fig)\n\n# High-resolution PNG for publications\nsave(\"high_res.png\", fig, px_per_unit=3)  # 900 DPI equivalent\n\n","title":"Exporting Plots"},{"category":"section","location":"guide/#Troubleshooting","page":"User Guide","text":"","title":"Troubleshooting"},{"category":"section","location":"guide/#Plots-not-displaying-in-REPL","page":"User Guide","text":"Solution: Activate the CairoMakie backend explicitly\n\nusing CairoMakie\nCairoMakie.activate!()\n\nresults = diagnose_missing(df)","title":"Plots not displaying in REPL"},{"category":"section","location":"guide/#\"Directory-does-not-exist\"-error","page":"User Guide","text":"Solution: Create the output directory before generating reports\n\noutput_dir = \"reports\"\n!isdir(output_dir) && mkdir(output_dir)\n\nresults = diagnose_missing(df, report=true, output=\"reports/analysis.html\")","title":"\"Directory does not exist\" error"},{"category":"section","location":"guide/#Out-of-memory-with-large-datasets","page":"User Guide","text":"Solution: Use display=false to skip plot rendering\n\n# For very large datasets (>100K rows)\nresults = diagnose_missing(df, display=false)\n\n# Access statistics only\nprintln(results[:stats])\n\n","title":"Out of memory with large datasets"},{"category":"section","location":"guide/#Performance-Tips","page":"User Guide","text":"","title":"Performance Tips"},{"category":"section","location":"guide/#For-Large-Datasets-(10K-rows)","page":"User Guide","text":"# Skip interactive display\nresults = diagnose_missing(df, display=false)\n\n# Generate report directly\nresults = diagnose_missing(df, \"report.html\", verbose=true)\n\n","title":"For Large Datasets (>10K rows)"},{"category":"section","location":"guide/#Complete-Reference","page":"User Guide","text":"For the full user guide with all examples, workflows, and advanced usage, see:\n\nUSER_GUIDE.md","title":"Complete Reference"},{"category":"section","location":"api/#API-Reference","page":"API Reference","text":"This page provides detailed documentation for all public functions in MissingDataViz.jl.\n\n","title":"API Reference"},{"category":"section","location":"api/#Pattern-Detection","page":"API Reference","text":"Functions for detecting and analyzing missing data patterns.\n\n","title":"Pattern Detection"},{"category":"section","location":"api/#Visualizations","page":"API Reference","text":"","title":"Visualizations"},{"category":"section","location":"api/#Matrix-Heatmap","page":"API Reference","text":"","title":"Matrix Heatmap"},{"category":"section","location":"api/#Bar-Charts","page":"API Reference","text":"","title":"Bar Charts"},{"category":"section","location":"api/#Correlation-Matrix","page":"API Reference","text":"","title":"Correlation Matrix"},{"category":"section","location":"api/#Overview-Dashboard","page":"API Reference","text":"","title":"Overview Dashboard"},{"category":"section","location":"api/#Reports-and-Workflows","page":"API Reference","text":"Functions for generating reports and complete workflows.\n\n","title":"Reports and Workflows"},{"category":"section","location":"api/#Data-Structures","page":"API Reference","text":"","title":"Data Structures"},{"category":"section","location":"api/#Utility-Functions","page":"API Reference","text":"","title":"Utility Functions"},{"category":"section","location":"api/#Index","page":"API Reference","text":"","title":"Index"},{"category":"function","location":"api/#MissingDataViz.missing_pattern","page":"API Reference","text":"missing_pattern(df::DataFrame) → BitMatrix\n\nConverts a DataFrame to a binary matrix (true = missing, false = present). OPTIMIZED: Uses Julia's efficient broadcast for minimal allocations.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nBitMatrix: Binary matrix with same dimensions as df (true = missing, false = present)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\npattern = missing_pattern(df)\n# 3×2 BitMatrix:\n#  0  0\n#  1  0\n#  0  1\n\n\n\n\n\n","title":"MissingDataViz.missing_pattern"},{"category":"function","location":"api/#MissingDataViz.missing_count","page":"API Reference","text":"missing_count(df::DataFrame) → Vector{Int}\n\nCounts the absolute number of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Int}: Number of missing values for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, missing, 6])\ncounts = missing_count(df)  # [1, 2]\n\n\n\n\n\n","title":"MissingDataViz.missing_count"},{"category":"function","location":"api/#MissingDataViz.missing_percentage","page":"API Reference","text":"missing_percentage(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentages (0.0 to 100.0) for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\npct = missing_percentage(df)  # [33.33, 0.0]\n\n\n\n\n\n","title":"MissingDataViz.missing_percentage"},{"category":"function","location":"api/#MissingDataViz.pattern_counts","page":"API Reference","text":"pattern_counts(df::DataFrame) → Dict{Vector{Bool}, Int}\n\nIdentifies unique missing data patterns and counts their occurrences. OPTIMIZED: Uses views, pre-allocation, and get() for better performance.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDict{Vector{Bool}, Int}: Dictionary mapping each unique pattern to its count\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3, missing], B=[missing, 2, missing, 2])\ncounts = pattern_counts(df)\n# Dict with patterns as keys, counts as values\n\n\n\n\n\n","title":"MissingDataViz.pattern_counts"},{"category":"function","location":"api/#MissingDataViz.pattern_frequency","page":"API Reference","text":"pattern_frequency(df::DataFrame) → Vector{Tuple{Vector{Bool}, Int}}\n\nReturns unique patterns sorted by frequency (most common first).\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Tuple{Vector{Bool}, Int}}: Vector of (pattern, count) tuples sorted by count descending\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nfreq = pattern_frequency(df)\n# [(pattern1, count1), (pattern2, count2), ...] sorted by count\n\n\n\n\n\n","title":"MissingDataViz.pattern_frequency"},{"category":"function","location":"api/#MissingDataViz.row_missing_stats","page":"API Reference","text":"row_missing_stats(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values for each row. OPTIMIZED: Pre-allocation and single-pass calculation.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentage of missing values per row (0.0 to 100.0)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nrow_stats = row_missing_stats(df)\n# [50.0, 50.0, 50.0]  (each row has 1 out of 2 missing)\n\n\n\n\n\n","title":"MissingDataViz.row_missing_stats"},{"category":"function","location":"api/#MissingDataViz.column_missing_distribution","page":"API Reference","text":"column_missing_distribution(df::DataFrame) → DataFrame\n\nCreates a detailed distribution table of missing values by column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDataFrame: Table with columns column_name, n_missing, pct_missing, n_present\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\ndist = column_missing_distribution(df)\n# 2×4 DataFrame with distribution stats\n\n\n\n\n\n","title":"MissingDataViz.column_missing_distribution"},{"category":"function","location":"api/#MissingDataViz.extreme_patterns","page":"API Reference","text":"extreme_patterns(df::DataFrame) → NamedTuple\n\nIdentifies extreme cases: rows/columns that are 100% missing or 100% complete.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple with fields:\nrows_all_missing::Vector{Int}: Row indices where all values are missing\nrows_all_complete::Vector{Int}: Row indices where no values are missing\ncols_all_missing::Vector{Int}: Column indices where all values are missing\ncols_all_complete::Vector{Int}: Column indices where no values are missing\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[missing, 1], B=[missing, missing])\nextremes = extreme_patterns(df)\n# extremes.rows_all_missing == [1]\n# extremes.cols_all_missing == [2]\n\n\n\n\n\n","title":"MissingDataViz.extreme_patterns"},{"category":"function","location":"api/#MissingDataViz.summarize_missing","page":"API Reference","text":"summarize_missing(df::DataFrame) → NamedTuple\n\nGenerates a comprehensive summary of missing data patterns and statistics.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple containing:\ntotal_cells::Int: Total number of cells in DataFrame\nn_missing::Int: Total number of missing values\npct_missing::Float64: Overall percentage of missing values\nby_column::DataFrame: Distribution statistics by column\nby_row::Vector{Float64}: Percentage missing per row\nextremes::NamedTuple: Extreme patterns (all missing/complete rows/cols)\ntop_patterns::Vector: Top 5 most frequent patterns\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\nsummary = summarize_missing(df)\nprintln(\"Total missing: \", summary.n_missing)\nprintln(\"By column: \", summary.by_column)\n\n\n\n\n\n","title":"MissingDataViz.summarize_missing"},{"category":"function","location":"api/#MissingDataViz.missing_correlation","page":"API Reference","text":"missing_correlation(df::DataFrame)\n\nCalculate the Pearson correlation matrix between missing data patterns across columns.\n\nThis function converts the DataFrame to a binary matrix (1 = missing, 0 = present) and computes pairwise correlations between columns. Positive correlations indicate columns that tend to have missing values together, while negative correlations suggest opposite patterns.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\n\nReturns\n\nMatrix{Float64}: Correlation matrix (ncols × ncols) where each entry (i,j)  represents the correlation between missingness patterns of columns i and j\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, 2, 3, missing, 5],      # Correlates with A\n    C = [1, 2, missing, 4, missing]       # Different pattern\n)\n\ncorr_matrix = missing_correlation(df)\n# corr_matrix[1,2] will be high (A and B missing together)\n\nNotes\n\nReturns NaN for columns with no missing values (constant pattern, no variance)\nDiagonal elements are always 1.0 (perfect self-correlation)\nCorrelation ranges from -1.0 (opposite patterns) to 1.0 (identical patterns)\n\n\n\n\n\n","title":"MissingDataViz.missing_correlation"},{"category":"function","location":"api/#MissingDataViz.plot_missing_matrix","page":"API Reference","text":"plot_missing_matrix(df::DataFrame; kwargs...)\n\nCreate a heatmap visualizing missing data patterns in a DataFrame with customization options.\n\nArguments\n\ndf::DataFrame: DataFrame to visualize\n\nKeyword Arguments\n\nfigsize::Tuple{Int,Int}: Figure dimensions in pixels. Default: (1000, 600)\ncolormap::Symbol: Color scheme for the heatmap. Default: :grays\nshow_sparkline::Bool: Display sparkline showing % missing per row. Default: true\nmax_rows_display::Int: Maximum number of rows to display. Use -1 for no limit. Default: 5000\nlabels::NamedTuple: Custom labels for plot elements. Default labels in English.\nxlabel: X-axis label (default: \"Variables\")\nylabel: Y-axis label (default: \"Observations\")\ntitle: Plot title (default: \"Missing Data Pattern\")\ncolorbar_label: Colorbar label (default: \"Data Status\")\ncolorbar_present: Label for present values (default: \"Present\")\ncolorbar_missing: Label for missing values (default: \"Missing\")\nsparkline_ylabel: Sparkline Y-axis label (default: \"% Missing\")\n\nReturns\n\nFigure: Makie Figure object containing the heatmap\n\nExamples\n\nusing MissingDataViz\nusing DataFrames\n\ndf = DataFrame(\n    A = [1, missing, 3, 4, missing],\n    B = [missing, 2, 3, missing, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Basic usage\nfig = plot_missing_matrix(df)\n\n# French labels\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Variables\",\n    ylabel = \"Observations\",\n    title = \"Motif de Données Manquantes\",\n    colorbar_label = \"Statut\",\n    colorbar_present = \"Présent\",\n    colorbar_missing = \"Manquant\",\n    sparkline_ylabel = \"% Manquant\"\n))\n\n# Medical context\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Clinical Variables\",\n    ylabel = \"Patients\",\n    title = \"Missing Data in Patient Records\"\n))\n\n# Custom size without sparkline\nfig = plot_missing_matrix(df; figsize=(800, 600), show_sparkline=false)\n\n# Colorblind-friendly colormap\nfig = plot_missing_matrix(df; colormap=:viridis)\n\n# Display more rows\nfig = plot_missing_matrix(df; max_rows_display=10000)\n\n# Combined customization\nfig = plot_missing_matrix(df; \n    figsize=(1200, 800), \n    colormap=:thermal,\n    show_sparkline=true,\n    max_rows_display=3000,\n    labels=(xlabel=\"Features\", ylabel=\"Samples\")\n)\n\nNotes\n\nBlack = missing value (with default :grays colormap)\nWhite = present value (with default :grays colormap)\nFor datasets >50 columns, only the first 50 columns are displayed\nAvailable colormaps: :grays, :viridis, :plasma, :thermal, :RdBu, etc.\nPartial label override is supported (only specify labels you want to change)\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_matrix"},{"category":"function","location":"api/#MissingDataViz.plot_missing_bars","page":"API Reference","text":"plot_missing_bars(df::DataFrame; sort::Bool=true, figsize::Tuple{Int,Int}=(800, 600), \n                  threshold::Union{Nothing,Float64}=nothing, orientation::Symbol=:auto)\n\nCreate a bar chart showing the percentage of missing values for each column.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nsort::Bool=true: Sort columns by missing percentage (descending)\nfigsize::Tuple{Int,Int}=(800, 600): Figure dimensions (width, height)\nthreshold::Union{Nothing,Float64}=nothing: Display horizontal threshold line at specified percentage (0-100)\norientation::Symbol=:auto: Bar orientation (:vertical, :horizontal, or :auto which uses horizontal if >20 columns)\n\nReturns\n\nFigure: Makie Figure object containing the bar chart\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, missing, missing, 4, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Basic bar chart\nfig = plot_missing_bars(df)\n\n# With custom threshold line at 30%\nfig = plot_missing_bars(df, threshold=30.0)\n\n# Horizontal bars for many columns\nfig = plot_missing_bars(df, orientation=:horizontal)\n\nColor coding\n\nBlue: < 20% missing\nOrange: 20-50% missing\nRed: >= 50% missing\n\nNotes\n\nVertical orientation (default for ≤20 columns): No label overlap issues\nHorizontal orientation (automatic for >20 columns): If column labels overlap,  increase figure height: figsize=(800, 1200) or use figsize=(1000, 50*n_cols)\nFor very wide datasets (>50 columns), consider filtering to most relevant columns first\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_bars"},{"category":"function","location":"api/#MissingDataViz.plot_missing_correlation","page":"API Reference","text":"plot_missing_correlation(df::DataFrame; figsize::Tuple{Int,Int}=(800, 800), \n                         show_values::Bool=:auto)\n\nCreate a heatmap visualization of the missing data pattern correlation matrix.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nfigsize::Tuple{Int,Int}=(800, 800): Figure dimensions (width, height)\nshow_values::Bool=:auto: Display correlation values in cells. Auto shows values if ≤10 columns\n\nReturns\n\nFigure: Makie Figure object containing the correlation heatmap\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, 2, 3, missing, 5],\n    C = [1, 2, missing, 4, missing]\n)\n\nfig = plot_missing_correlation(df)\nfig = plot_missing_correlation(df, show_values=true)  # Force display values\n\nInterpretation\n\nRed (positive correlation): Columns tend to have missing values together\nBlue (negative correlation): When one column is missing, the other tends to be present\nWhite (zero correlation): No relationship between missing patterns\nDiagonal = 1.0: Each column perfectly correlates with itself\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_correlation"},{"category":"function","location":"api/#MissingDataViz.plot_missing_overview","page":"API Reference","text":"plot_missing_overview(df::DataFrame; \n                      figsize::Tuple{Int,Int}=(1800, 600),\n                      layout::Symbol=:horizontal,\n                      threshold::Union{Nothing,Float64}=nothing,\n                      show_correlation_values::Union{Bool,Symbol}=:auto)\n\nCreate a comprehensive overview dashboard combining all three missing data visualizations.\n\nCombines:\n\nMissing data matrix (left/top): Shows where missing values occur row-by-row\nBar chart (center): Shows percentage of missing values per column\nCorrelation matrix (right/bottom): Shows relationships between missing patterns\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nfigsize::Tuple{Int,Int}=(1800, 600): Figure dimensions (width, height)\nlayout::Symbol=:horizontal: Layout (:horizontal = 1×3 grid, :vertical = 3×1 grid)\nthreshold::Union{Nothing,Float64}=nothing: Optional threshold line for bar chart\nshow_correlation_values::Union{Bool,Symbol}=:auto: Show values in correlation heatmap\n\nReturns\n\nFigure: Makie Figure containing all three plots in unified layout\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, missing, missing, 4, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Default horizontal layout\nfig = plot_missing_overview(df)\n\n# Vertical layout\nfig = plot_missing_overview(df, layout=:vertical, figsize=(1000, 1800))\n\n# With threshold line on bar chart\nfig = plot_missing_overview(df, threshold=30.0)\n\nUse Cases\n\nQuick audit: Complete picture of missing data in single view\nExecutive reports: Comprehensive visual for presentations\nExploratory analysis: Identify patterns, severity, and correlations simultaneously\nBefore imputation: Understand data structure before choosing imputation strategy\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_overview"},{"category":"function","location":"api/#MissingDataViz.generate_html_report","page":"API Reference","text":"generate_html_report(df::DataFrame, output_file::String;\n                     title::String=\"Missing Data Analysis Report\",\n                     run_mcar_tests::Bool=false,\n                     alpha::Float64=0.05,\n                     mcar_results=nothing)\n\nGenerate a comprehensive HTML report with missing data analysis and visualizations.\n\nCreates a standalone HTML file containing:\n\nSummary statistics table (missing count and percentage per column)\nMissing data matrix heatmap\nBar chart of missing percentages\nCorrelation matrix of missingness patterns\nCombined overview dashboard\nOptional: MCAR diagnostic section with test results and recommendations\n\nAll plots are embedded as base64-encoded PNG images, making the report a single self-contained file with no external dependencies.\n\nArguments\n\ndf::DataFrame: Input data to analyze\noutput_file::String: Path where HTML report will be saved\nRelative paths are resolved from current working directory (pwd())\nAbsolute paths are used as-is\ntitle::String=\"Missing Data Analysis Report\": Report title displayed in header\nrun_mcar_tests::Bool=false: Whether to run MCAR tests and add diagnostic section\nfalse (default): Basic report only — faster, no statistical tests\ntrue: Full report with MCAR diagnostic section (adds a few seconds)\nalpha::Float64=0.05: Significance threshold for MCAR tests (only used if run_mcar_tests=true)\nmcar_results=nothing: Pre-computed MCAR results (MCARTestComparison) to inject directly.\nnothing (default): Results are computed internally when run_mcar_tests=true\nProvide a pre-computed value to avoid double execution when called from full_missing_diagnosis\nWhen provided, run_mcar_tests must also be true for the section to render\n\nReturns\n\nString: Absolute path to the generated HTML file\n\nOutput File Path Behavior\n\n# Relative path → saved in current directory\ngenerate_html_report(df, \"report.html\")\n# → Saved at: pwd()/report.html\n\n# Absolute path → saved at specified location\ngenerate_html_report(df, \"/home/user/reports/analysis.html\")\n# → Saved at: /home/user/reports/analysis.html\n\n# Check current directory\npwd()  # See where relative paths will be saved\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data with missing values\ndf = DataFrame(\n    Age    = [25, missing, 30, missing, 35],\n    Income = [50000, 60000, missing, 70000, missing],\n    Score  = [85, 90, missing, missing, 95]\n)\n\n# Generate basic report (no MCAR tests)\npath = generate_html_report(df, \"missing_analysis.html\")\nprintln(\"Report saved to: $path\")\n\n# Generate full report with MCAR diagnostic section\npath = generate_html_report(df, \"full_report.html\",\n                             title=\"Q4 2024 Data Quality Report\",\n                             run_mcar_tests=true)\n\n# Generate report with custom significance threshold\npath = generate_html_report(df, \"strict_report.html\",\n                             run_mcar_tests=true,\n                             alpha=0.01)\n\n# Inject pre-computed results (avoids double execution)\nmcar = compare_mcar_tests(df)\npath = generate_html_report(df, \"fast_report.html\",\n                             run_mcar_tests=true,\n                             mcar_results=mcar)\n\n# Open in browser (cross-platform)\nif Sys.iswindows()\n    run(`cmd /c start $path`)\nelseif Sys.isapple()\n    run(`open $path`)\nelse\n    run(`xdg-open $path`)\nend\n\nPerformance\n\nBasic report (runmcartests=false):            150-300ms for datasets with <10,000 rows\nFull report  (runmcartests=true):             +2-10s depending on dataset size and column count\nFull report  (mcar_results pre-computed):       ~same as basic — no test re-execution\nReport file size: ~500KB - 2MB depending on data size\nMemory usage: ~50MB peak (temporary plot rendering)\n\nNote\n\nThis function generates all visualizations automatically. Plots are always embedded as base64 PNG images for maximum portability.\n\nSee Also\n\nfull_missing_diagnosis: All-in-one pipeline (recommended entry point)\ndiagnose_missing: Legacy all-in-one analysis workflow\nplot_missing_diagnosis: Interactive dashboard (Phase 1 + Phase 2)\nCairoMakie.save(): For exporting individual plots to PNG/PDF/SVG\n\nThrows\n\nErrorException: If output directory doesn't exist or is not writable\nArgumentError: If DataFrame is empty or has no columns\n\n\n\n\n\n","title":"MissingDataViz.generate_html_report"},{"category":"function","location":"api/#MissingDataViz.diagnose_missing","page":"API Reference","text":"diagnose_missing(df::DataFrame; \n                 report::Bool=false,\n                 output::String=\"missing_report.html\",\n                 display::Bool=!report,\n                 verbose::Bool=false)\n\nPerform comprehensive missing data analysis with automatic visualization and reporting.\n\nThis is the main entry point for missing data diagnosis. It provides two modes:\n\nInteractive mode (report=false): Display plots and return statistics\nBatch mode (report=true): Generate HTML report silently\n\nArguments\n\ndf::DataFrame: Input data to analyze\nreport::Bool=false: Generate HTML report (batch mode)\nfalse (default): Interactive mode - display plots in current environment\ntrue: Batch mode - generate HTML file silently\noutput::String=\"missing_report.html\": Output path for HTML report\nOnly used when report=true\nRelative paths resolved from pwd()\nAbsolute paths used as-is\ndisplay::Bool=!report: Display plots interactively\nIgnored if report=true (batch mode implies no interactive display)\nOnly effective in interactive mode (report=false)\nverbose::Bool=false: Enable detailed logging\nfalse (default): Minimal output - only final result message\ntrue: Detailed logging of each step\n\nReturns\n\nDict with the following structure:\nDict(\n    :stats => Dict(\n        :total_missing => Int,\n        :total_cells => Int,\n        :overall_percentage => Float64,\n        :columns => Dict(\"col\" => Dict(:count, :percentage))\n    ),\n    :figures => Dict(\n        :matrix => Figure,\n        :bars => Figure,\n        :correlation => Figure,\n        :overview => Figure\n    ),\n    :report_path => String  # Only present if report=true\n)\n\nBehavior\n\nInteractive Mode (report=false)\n\n# Display plots and return statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\n\n# Access figures for further manipulation\nmatrix_fig = results[:figures][:matrix]\nsave(\"custom_matrix.png\", matrix_fig)  # Export with CairoMakie\n\n# Suppress display (compute only)\nresults = diagnose_missing(df, display=false)\n\nBatch Mode (report=true)\n\n# Generate HTML report silently\nresults = diagnose_missing(df, report=true)\nprintln(\"Report: \", results[:report_path])\n\n# Custom output path\nresults = diagnose_missing(df, report=true, output=\"analysis/report.html\")\n\n# Verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → \"Computing missing data statistics...\"\n# → \"Generating visualizations...\"\n# → \"Generating HTML report...\"\n# → \"Report generated: /path/to/report.html\"\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# Example 1: Quick interactive analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Example 2: Generate report for sharing\nresults = diagnose_missing(df, report=true, output=\"team_review.html\")\n# → Creates team_review.html\n# → Silent execution (no plots displayed)\n\n# Example 3: Debug mode with verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → Shows detailed progress of each step\n\n# Example 4: Compute stats without displaying plots\nresults = diagnose_missing(df, display=false)\n# → No visual output, only statistics computed\n\n# Example 5: Access specific statistics\nresults = diagnose_missing(df)\nfor (col, stats) in results[:stats][:columns]\n    if stats[:percentage] > 20\n        println(\"$col has $(stats[:percentage])% missing - investigate!\")\n    end\nend\n\nPerformance\n\nInteractive mode: 150-250ms (display time depends on backend)\nBatch mode: 200-350ms (includes HTML generation and file write)\nMemory: ~50-100MB peak (temporary plot rendering)\n\nNotes\n\nThe display parameter is ignored when report=true to avoid confusion\nIn batch mode, plots are never displayed interactively\nAll plots are always generated (for both modes)\nUse verbose=true for debugging or progress monitoring\n\nSee Also\n\ngenerate_html_report: Generate HTML report only (no interactive display)\nplot_missing_overview: Generate combined overview plot only\nCairoMakie.save(): Export individual plots to files\n\nThrows\n\nArgumentError: If DataFrame is empty or has no columns\nErrorException: If report output directory doesn't exist (batch mode only)\n\n\n\n\n\ndiagnose_missing(df::DataFrame, output_file::String; kwargs...)\n\nConvenience method: Generate report by default when output file is specified.\n\nThis is a shorthand for diagnose_missing(df; report=true, output=output_file, kwargs...).\n\nExamples\n\n# These two calls are equivalent:\ndiagnose_missing(df, \"report.html\")\ndiagnose_missing(df, report=true, output=\"report.html\")\n\n\n\n\n\n","title":"MissingDataViz.diagnose_missing"},{"category":"type","location":"api/#MissingDataViz.PatternInfo","page":"API Reference","text":"PatternInfo\n\nStructure to store information about a specific missing data pattern.\n\nFields\n\npattern::Vector{Bool}: The binary pattern (true = missing, false = present)\ncount::Int: Number of rows with this pattern\nfrequency::Float64: Percentage of rows with this pattern (0.0 to 100.0)\nrow_indices::Vector{Int}: Indices of rows that have this pattern\n\nExamples\n\ninfo = PatternInfo(\n    pattern = [true, false, true],\n    count = 5,\n    frequency = 25.0,\n    row_indices = [2, 7, 10, 15, 18]\n)\n\n\n\n\n\n","title":"MissingDataViz.PatternInfo"},{"category":"function","location":"api/#MissingDataViz.validate_dataframe","page":"API Reference","text":"validate_dataframe(df)\n\nValidate that df is a valid DataFrame for processing.\n\nThrows\n\nArgumentError: If df is not a DataFrame\nInvalidDataFrameError: If DataFrame is empty or has no columns\n\nReturns\n\nNothing if validation passes.\n\n\n\n\n\n","title":"MissingDataViz.validate_dataframe"},{"category":"section","location":"getting-started/#Getting-Started","page":"Getting Started","text":"This guide will help you install MissingDataViz.jl and create your first visualization in under 5 minutes.\n\n","title":"Getting Started"},{"category":"section","location":"getting-started/#Installation","page":"Getting Started","text":"","title":"Installation"},{"category":"section","location":"getting-started/#Method-1:-From-Julia-General-Registry-(Recommended)","page":"Getting Started","text":"Once the package is registered (after v0.1.0 release):\n\nusing Pkg\nPkg.add(\"MissingDataViz\")","title":"Method 1: From Julia General Registry (Recommended)"},{"category":"section","location":"getting-started/#Method-2:-From-GitHub-(Current)","page":"Getting Started","text":"For the latest development version:\n\nusing Pkg\nPkg.add(url=\"https://github.com/DescarteS96/MissingDataViz.jl\")","title":"Method 2: From GitHub (Current)"},{"category":"section","location":"getting-started/#Method-3:-Local-Development","page":"Getting Started","text":"If you've cloned the repository:\n\nusing Pkg\nPkg.activate(\"/path/to/MissingDataViz\")\nPkg.instantiate()\n\n","title":"Method 3: Local Development"},{"category":"section","location":"getting-started/#Quick-Start:-Your-First-Plot-in-5-Minutes","page":"Getting Started","text":"","title":"Quick Start: Your First Plot in 5 Minutes"},{"category":"section","location":"getting-started/#Step-1:-Load-the-package","page":"Getting Started","text":"using MissingDataViz\nusing DataFrames","title":"Step 1: Load the package"},{"category":"section","location":"getting-started/#Step-2:-Create-sample-data-with-missing-values","page":"Getting Started","text":"# Create a DataFrame with some missing values\ndf = DataFrame(\n    PatientID = 1:10,\n    Age = [25, missing, 35, 42, missing, 28, 31, missing, 45, 38],\n    Weight = [70, 65, missing, 80, 75, missing, 68, 72, missing, 77],\n    BloodPressure = [120, 118, missing, 135, missing, 122, missing, 128, 140, 125],\n    Cholesterol = [missing, 180, 195, missing, 210, 185, missing, 200, 220, 190]\n)","title":"Step 2: Create sample data with missing values"},{"category":"section","location":"getting-started/#Step-3:-Generate-complete-analysis","page":"Getting Started","text":"# One-line complete diagnosis\nresults = diagnose_missing(df)\n\nWhat happens:\n\nFour plots are automatically displayed:\nMissing data matrix (heatmap showing pattern)\nBar chart (percentage missing per column)\nCorrelation matrix (which columns tend to be missing together)\nOverview dashboard (all three combined)","title":"Step 3: Generate complete analysis"},{"category":"section","location":"getting-started/#Step-4:-Access-statistics","page":"Getting Started","text":"# Get detailed statistics\nstats = results[:stats]\n\nprintln(\"Total missing values: \", stats[:total_missing])\nprintln(\"Overall percentage: \", stats[:overall_percentage], \"%\")\n\n# Per-column breakdown\nfor (col, info) in stats[:columns]\n    println(\"$col: $(info[:percentage])% missing ($(info[:count]) values)\")\nend\n\nOutput:\n\nTotal missing values: 13\nOverall percentage: 32.5%\nPatientID: 0.0% missing (0 values)\nAge: 30.0% missing (3 values)\nWeight: 30.0% missing (3 values)\nBloodPressure: 30.0% missing (3 values)\nCholesterol: 40.0% missing (4 values)\n\n","title":"Step 4: Access statistics"},{"category":"section","location":"getting-started/#Save-Your-Work","page":"Getting Started","text":"","title":"Save Your Work"},{"category":"section","location":"getting-started/#Export-individual-plots","page":"Getting Started","text":"using CairoMakie\n\n# Save the matrix plot\nsave(\"missing_matrix.png\", results[:figures][:matrix])\n\n# Save the overview dashboard\nsave(\"overview.pdf\", results[:figures][:overview])","title":"Export individual plots"},{"category":"section","location":"getting-started/#Generate-HTML-report","page":"Getting Started","text":"# Create standalone HTML report\ndiagnose_missing(df, report=true, output=\"analysis_report.html\")\n\n# Open it in your browser manually, or:\n# Windows: run(`cmd /c start analysis_report.html`)\n# macOS: run(`open analysis_report.html`)\n# Linux: run(`xdg-open analysis_report.html`)\n\n","title":"Generate HTML report"},{"category":"section","location":"getting-started/#Next-Steps","page":"Getting Started","text":"","title":"Next Steps"},{"category":"section","location":"getting-started/#Explore-Individual-Visualizations","page":"Getting Started","text":"Instead of diagnose_missing(), you can create plots individually:\n\n# Just the matrix heatmap\nfig1 = plot_missing_matrix(df)\n\n# Just the bar chart\nfig2 = plot_missing_bars(df)\n\n# Just the correlation matrix\nfig3 = plot_missing_correlation(df)\n\n# Combined overview\nfig4 = plot_missing_overview(df)","title":"Explore Individual Visualizations"},{"category":"section","location":"getting-started/#Customize-Your-Plots","page":"Getting Started","text":"All plotting functions accept customization options:\n\n# Custom size and threshold\nplot_missing_bars(df, \n    figsize=(1000, 700),\n    threshold=25.0  # Show line at 25% missing\n)\n\n# Horizontal orientation for many columns\nplot_missing_bars(df, orientation=:horizontal)\n\n# Hide sparkline in matrix plot\nplot_missing_matrix(df, show_sparkline=false)","title":"Customize Your Plots"},{"category":"section","location":"getting-started/#Pattern-Detection","page":"Getting Started","text":"Get detailed pattern analysis:\n\n# Summary of all missing data patterns\nsummary = summarize_missing(df)\n\nprintln(\"Total cells: \", summary.total_cells)\nprintln(\"Missing cells: \", summary.n_missing)\nprintln(\"Top 5 patterns:\")\nfor (pattern, count) in summary.top_patterns\n    println(\"  Pattern: \", pattern, \" → \", count, \" rows\")\nend\n\n","title":"Pattern Detection"},{"category":"section","location":"getting-started/#Common-Use-Cases","page":"Getting Started","text":"","title":"Common Use Cases"},{"category":"section","location":"getting-started/#1.-Quick-Data-Quality-Check","page":"Getting Started","text":"# Load your data\ndf = CSV.read(\"mydata.csv\", DataFrame)\n\n# Instant visual diagnosis\ndiagnose_missing(df)","title":"1. Quick Data Quality Check"},{"category":"section","location":"getting-started/#2.-Pre-Processing-for-Machine-Learning","page":"Getting Started","text":"# Check missing data before training\nresults = diagnose_missing(df, display=false)\n\n# Identify problematic columns\nhigh_missing = [\n    col for (col, stats) in results[:stats][:columns]\n    if stats[:percentage] > 30.0\n]\n\nprintln(\"Consider removing or imputing: \", high_missing)","title":"2. Pre-Processing for Machine Learning"},{"category":"section","location":"getting-started/#3.-Generate-Report-for-Stakeholders","page":"Getting Started","text":"# Create professional HTML report\ndiagnose_missing(df, \n    report=true, \n    output=\"data_quality_report_$(Dates.today()).html\"\n)\n\n","title":"3. Generate Report for Stakeholders"},{"category":"section","location":"getting-started/#Troubleshooting","page":"Getting Started","text":"","title":"Troubleshooting"},{"category":"section","location":"getting-started/#Plots-not-displaying","page":"Getting Started","text":"If plots don't appear automatically:\n\nusing CairoMakie\nCairoMakie.activate!()\n\nresults = diagnose_missing(df)","title":"Plots not displaying"},{"category":"section","location":"getting-started/#Out-of-memory-with-large-datasets","page":"Getting Started","text":"For very large datasets (>100k rows):\n\n# Compute statistics without rendering plots\nresults = diagnose_missing(df, display=false)\n\n# Access stats without creating figures\nprintln(results[:stats])","title":"Out of memory with large datasets"},{"category":"section","location":"getting-started/#File-path-issues-on-Windows","page":"Getting Started","text":"Use double backslashes or raw strings:\n\n# Method 1: Double backslashes\ndiagnose_missing(df, report=true, output=\"C:\\\\Users\\\\Name\\\\report.html\")\n\n# Method 2: Raw string\ndiagnose_missing(df, report=true, output=raw\"C:\\Users\\Name\\report.html\")\n\n# Method 3: Forward slashes (works on Windows too)\ndiagnose_missing(df, report=true, output=\"C:/Users/Name/report.html\")\n\n","title":"File path issues on Windows"},{"category":"section","location":"getting-started/#What-You've-Learned","page":"Getting Started","text":"✅ Install MissingDataViz.jl   ✅ Create basic visualizations with one line of code   ✅ Access detailed statistics programmatically   ✅ Export plots and generate reports   ✅ Customize visualizations for your needs  \n\n","title":"What You've Learned"},{"category":"section","location":"getting-started/#Where-to-Go-Next","page":"Getting Started","text":"API Reference: Complete function documentation\nUser Guide: Advanced workflows and batch processing\nExamples: Real-world use cases\n\n","title":"Where to Go Next"},{"category":"section","location":"getting-started/#Need-Help?","page":"Getting Started","text":"📖 Full Documentation\n🐛 Report a Bug\n💬 Ask a Question","title":"Need Help?"},{"category":"section","location":"#MissingDataViz.jl","page":"Home","text":"Professional missing data visualization and diagnosis for Julia DataFrames\n\n","title":"MissingDataViz.jl"},{"category":"section","location":"#Overview","page":"Home","text":"MissingDataViz.jl provides comprehensive tools for analyzing and visualizing missing data patterns in tabular datasets. It combines intuitive visualizations with robust pattern detection to help you understand the structure of missingness in your data.\n\nKey Features:\n\n🔍 Pattern Detection: Identify unique missing data patterns and their frequencies\n📊 Multiple Visualizations: Matrix heatmaps, bar charts, correlation matrices, overview dashboards\n📄 HTML Reports: Generate standalone reports with embedded visualizations\n💾 Export Flexibility: Save plots as PNG, PDF, or SVG\n⚡ One-Line Diagnosis: Complete analysis with diagnose_missing()\n\n","title":"Overview"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"MissingDataViz\")\n\nDevelopment version:\n\nusing Pkg\nPkg.add(url=\"https://github.com/DescarteS96/MissingDataViz.jl\")\n\n","title":"Installation"},{"category":"section","location":"#Quick-Start","page":"Home","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Generate HTML report for sharing\ndiagnose_missing(df, report=true, output=\"analysis.html\")\n# → Creates standalone HTML file\n\n","title":"Quick Start"},{"category":"section","location":"#Visualizations","page":"Home","text":"","title":"Visualizations"},{"category":"section","location":"#Missing-Data-Matrix","page":"Home","text":"fig = plot_missing_matrix(df)\n\nShows: Binary heatmap of missing values (black = missing, white = present) with optional sparkline showing % missing per row.","title":"Missing Data Matrix"},{"category":"section","location":"#Bar-Chart","page":"Home","text":"fig = plot_missing_bars(df)\n\nShows: Percentage of missing values per column, color-coded by severity (blue < 20%, orange 20-50%, red ≥ 50%).","title":"Bar Chart"},{"category":"section","location":"#Correlation-Matrix","page":"Home","text":"fig = plot_missing_correlation(df)\n\nShows: Correlation between missing data patterns across columns to detect co-occurrence.","title":"Correlation Matrix"},{"category":"section","location":"#Overview-Dashboard","page":"Home","text":"fig = plot_missing_overview(df)\n\nShows: Combined view of all three plots above in a single figure.\n\n","title":"Overview Dashboard"},{"category":"section","location":"#Workflows","page":"Home","text":"","title":"Workflows"},{"category":"section","location":"#Interactive-Analysis","page":"Home","text":"# Display plots and access statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall %: \", results[:stats][:overall_percentage])\n\n# Save individual plots\nusing CairoMakie\nsave(\"matrix.png\", results[:figures][:matrix])\nsave(\"overview.pdf\", results[:figures][:overview])","title":"Interactive Analysis"},{"category":"section","location":"#Batch-Reporting","page":"Home","text":"# Generate HTML report (no interactive display)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n# Open in browser\npath = results[:report_path]\n# Windows: run(`cmd /c start $path`)\n# macOS: run(`open $path`)\n# Linux: run(`xdg-open $path`)\n\n","title":"Batch Reporting"},{"category":"section","location":"#Navigation","page":"Home","text":"Pages = [\"api.md\", \"guide.md\"]\nDepth = 2\n\nAPI Reference: Complete function documentation\nUser Guide: Detailed workflows, troubleshooting, and examples\n\n","title":"Navigation"},{"category":"section","location":"#Performance","page":"Home","text":"Interactive mode: 150-250ms for typical datasets (1000 rows × 10 columns)\nBatch mode: 200-350ms (includes HTML generation)\nMaximum recommended size: 100k rows × 100 columns\n\n","title":"Performance"},{"category":"section","location":"#Support","page":"Home","text":"GitHub: github.com/DescarteS96/MissingDataViz.jl\nIssues: Report bugs or request features\nDocumentation: Online docs\n\n","title":"Support"},{"category":"section","location":"#Citation","page":"Home","text":"If you use MissingDataViz.jl in your research, please cite:\n\n@software{missingdataviz2026,\n  author = {Ballamou, Rene Fassou and Yenilmez, Ismail},\n  title  = {MissingDataViz.jl: Missing Data Visualization for Julia},\n  year   = {2026},\n  url    = {https://github.com/DescarteS96/MissingDataViz.jl}\n}\n\n","title":"Citation"},{"category":"section","location":"#Index","page":"Home","text":"","title":"Index"}]
}
